INSERT OR IGNORE INTO artists (id, name, handle, city, style, years, booked, rate, bio, pieces, rating, seed, email) VALUES ('mara', 'Mara Vael', '@maravael', 'Berlin, DE', 'Fine Line · Blackwork', 9, 'Booking Aug 2026', 180, 'Mara works in negative space and single-needle linework — quiet compositions that sit close to the skin. Every flash piece she releases is drawn once and retired the moment it is claimed.', 41, '4.98', 11, NULL);
INSERT OR IGNORE INTO artists (id, name, handle, city, style, years, booked, rate, bio, pieces, rating, seed, email) VALUES ('koto', 'Koto Arai', '@koto.irezumi', 'Osaka, JP', 'Irezumi · Neo-Traditional', 14, 'Waitlist open', 240, 'Trained in the tebori tradition, Koto reinterprets classical Japanese motifs as one-off contemporary plates. Bold line, restrained palette, no repeats.', 63, '5.00', 29, NULL);
INSERT OR IGNORE INTO artists (id, name, handle, city, style, years, booked, rate, bio, pieces, rating, seed, email) VALUES ('sol', 'Sol Reyes', '@sol.blackout', 'Mexico City, MX', 'Blackwork · Geometric', 7, 'Booking now', 160, 'Heavy black, sacred geometry, and ornamental linework. Sol releases limited plates that read as objects first, tattoos second.', 33, '4.95', 47, NULL);
INSERT OR IGNORE INTO artists (id, name, handle, city, style, years, booked, rate, bio, pieces, rating, seed, email) VALUES ('vera', 'Vera Lindqvist', '@vera.etch', 'Stockholm, SE', 'Etching · Realism', 11, 'Booking Sep 2026', 210, 'Etching-style stippling that mimics old engraving plates. Vera''s releases come with a hand-pulled proof — the design is never inked twice.', 52, '4.99', 71, NULL);

